"""T2F-Bench sample 003: MiniMax H3 Skill-format seven-shot benchmark."""
import csv,json,os
from pathlib import Path
root=Path(__file__).resolve().parents[1]
rows=list(csv.DictReader(open(Path(os.environ["TEMP"])/"t2f_bench_original.csv",encoding="utf-8-sig",newline="")))
assert len(rows)==100
script=rows[2]["ai_film_script"]
assert "CORLEONE COMPOUND" in script and "TOM HAGEN" in script and "KAY ADAMS" in script
shots=[["S01","Live-action cinematic drama in an overcast late-1970s suburban estate driveway after rain. Wide establishing shot of an imposing black wrought-iron gate, a stone wall, a gravel-and-stone driveway, wet asphalt and two stone lions visible farther inside. A mustard-yellow taxi moves slowly from frame left and comes to a complete stop beside the locked gate. From 0 to 2 seconds the car rolls along the wet curb; from 2 to 5 seconds the wheels settle and a passenger in a vivid red coat becomes visible through the rear window. Static camera at waist height with slight natural lens depth. Realistic reflections and restrained colors.","Tires whisper on damp pavement; a low idling engine and distant suburban birds are audible.","Sparse low piano notes with a quiet cello drone."],["S02","Live-action cinematic drama, grey daytime at the same rain-dampened estate gate. Medium full-body three-quarter shot of Kay, a fair-haired adult woman wearing a vivid red wool coat and matching red hat, standing beside the mustard-yellow taxi. From 0 to 1.5 seconds she closes the rear passenger door; from 1.5 to 3 seconds she leans toward the open driver's window and hands over her fare; from 3 to 5 seconds she straightens while the taxi pulls slowly away toward frame left. The camera trucks right with small amplitude at slow speed to keep Kay centered, iron bars and wet driveway behind her. She looks toward the gate, never at the lens.","A taxi door closes softly, banknotes brush fingertips, the engine accelerates and wheels hiss over wet road.","Three widely spaced piano notes at a slow tempo."],["S03","Live-action cinematic drama, overcast daylight at the imposing black iron estate gate with wet stone pavement. Medium-wide shot looking inward between the iron bars. Two security guards in beige trench coats remain motionless inside the locked gate, with the large stone house and symmetrical stone lions farther in the background. From 0 to 2 seconds the camera holds on the guards; from 2 to 5 seconds Tom, a dark-haired middle-aged man in a grey three-piece suit, walks briskly down the stone path from the mansion while buttoning his vest. Slow push in with small amplitude, natural unhurried steps and stable geometry.","Distant footsteps echo faintly on damp stone; fabric slides, faint wind moves the trees.","A low steady cello note under subdued piano pulses."],["S04","Live-action cinematic drama, late-1970s exterior of the same mansion gate under a heavy grey sky. Three-quarter medium shot: Tom, middle-aged and dark-haired, in a grey three-piece suit, comes to the pedestrian gate from inside; Kay in a vivid red coat and matching red hat waits on the street side. From 0 to 1.5 seconds Tom gives a small hand signal to a trench-coated guard; from 1.5 to 3 seconds the guard unlatches the narrow gate; from 3 to 5 seconds Tom steps through and turns toward Kay, leaving the gate ajar. Static eye-level framing, stable person positions, physically realistic hand and gate movements.","Metal latch clicks, hinged iron gate creaks briefly, wet footsteps and faint outdoor wind.","Soft piano dyads spaced far apart."],["S05","Live-action cinematic drama, eye-level over-the-shoulder medium two-shot beside a black iron estate gate on an overcast day. Kay, fair-haired, wearing a red wool coat and matching hat, faces Tom in a grey three-piece suit. Kay stands closer to camera in left profile, Tom faces her from slightly right; both look at each other's eyes, never into the camera. From 0 to 2 seconds Tom listens with a contained, guarded expression; from 2 to 3.5 seconds Kay glances toward the street behind her; from 3.5 to 5 seconds she turns back to him, visibly tense but composed. Tiny slow camera push in, understated realistic facial acting.","Light breeze passes through the gate, distant idling vehicles and soft fabric movement.","A held low cello tone, almost inaudible."],["S06","Live-action cinematic drama, near the same black wrought-iron gate in cool overcast daylight. Close medium two-shot, Kay in her red coat and hat on frame left and Tom in his grey suit on frame right. From 0 to 1.5 seconds Kay reaches into her small dark handbag; from 1.5 to 3 seconds she carefully withdraws one white paper envelope and offers it to Tom; from 3 to 5 seconds Tom briefly looks down at the envelope, then raises both hands slightly with his palms open and deliberately avoids taking it. Static camera at shoulder level, anatomically natural hands, a single unchanged envelope, restrained sorrow rather than theatrical expression.","Handbag material rubs softly, paper slides against cloth and a distant automobile passes.","Quiet low piano chord with slow decay."],["S07","Live-action cinematic drama, medium-wide rear three-quarter shot at the same estate's partly open iron pedestrian gate. The sky remains slate grey and the stone driveway is wet. Kay, the fair-haired woman in a vivid red coat and hat, stands beside Tom, the dark-haired man in a grey suit. From 0 to 1.5 seconds Tom softens his expression and turns toward the path; from 1.5 to 3 seconds he gently places his right hand at the upper back of Kay's coat; from 3 to 5 seconds they begin walking together through the open gate toward the stone lions and large mansion, with Kay carrying the white envelope in her left hand. Slow tracking shot follows from a few steps behind, maintaining clear positions, garment continuity and natural gait.","Subdued footsteps on damp stone, faint gate creak, distant birds and soft wool fabric movement.","A few gentle piano notes over a held low string tone."]]
items=[]
for name,visual,sound,music in shots:
    prompt="integrated_multimodal_description: [Shot 1] "+visual+"\n\noverall_soundscape: "+sound+"\n\nnon_diegetic_music: "+music
    items.append({"name":name,"set":{"140:131.prompt":prompt,"140:133.value":5,"92.filename_prefix":"video/015_t2f_003_h3_skill_"+name}})
baseline=json.loads((root/"tasks"/"014_t2f_002_h3_skill_5s.json").read_text(encoding="utf-8"))
task={"name":"015_t2f_003_h3_skill_5s","steps":[{"id":"video","workflow":baseline["steps"][0]["workflow"],"endpoint":baseline["steps"][0]["endpoint"],"foreach":items}]}
path=root/"tasks"/"015_t2f_003_h3_skill_5s.json"
path.write_text(json.dumps(task,ensure_ascii=False,indent=2),encoding="utf-8")
print("READY",path,"shots",len(items),"mean_prompt_chars",round(sum(len(x["set"]["140:131.prompt"]) for x in items)/len(items)))
